mapper.select:
SELECT tt.id AS id, tt.course_term_id AS courseTermId, at_.term_name AS termName, c.id AS courseId, c.course_name AS courseName, tt.teacher_id AS teacherId, t.name AS teacherName, tt.clazz_id AS clazzId, cz.clazz_name AS clazzName, tt.task_role AS taskRole, tt.weekly_hours AS weeklyHours, tt.status AS status FROM teaching_task tt JOIN course_term ct ON tt.course_term_id = ct.id AND ct.deleted = 0 JOIN academic_term at_ ON ct.term_id = at_.id JOIN course c ON ct.course_id = c.id AND c.deleted = 0 JOIN teacher t ON tt.teacher_id = t.id AND t.deleted = 0 LEFT JOIN clazz cz ON tt.clazz_id = cz.id WHERE tt.deleted = 0
AND ( (scope.teacherId != null AND tt.teacher_id = scope.teacherId) OR (scope.departmentId != null AND t.department_id = scope.departmentId) OR (scope.hasClassIds AND tt.clazz_id IN #{id}) )
AND tt.teacher_id = #{teacherId} AND ct.term_id = #{termId} AND tt.clazz_id = #{clazzId} ORDER BY tt.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM teaching_task tt JOIN course_term ct ON tt.course_term_id = ct.id AND ct.deleted = 0 JOIN teacher t ON tt.teacher_id = t.id AND t.deleted = 0 WHERE tt.deleted = 0
AND ( (scope.teacherId != null AND tt.teacher_id = scope.teacherId) OR (scope.departmentId != null AND t.department_id = scope.departmentId) OR (scope.hasClassIds AND tt.clazz_id IN #{id}) )
AND tt.teacher_id = #{teacherId} AND ct.term_id = #{termId} AND tt.clazz_id = #{clazzId}
